ord+2SaveIndex	equ ScreenIndex+2CurrentY	equ SaveIndex+2ThisOut	equ CurrentY+2LastOut	equ ThisOut+2SrcRef	equ LastOut+2DestRef	equ SrcRef+4ThisWord	equ DestRef+4HowManyWords	equ ThisWord+2WordCount	equ HowManyWords+2LineCount	equ WordCount+2HowFarToShift	equ LineCount+2CursorFlags	equ HowFarToShift+2TempRect	equ CursorFlags+2SaveRect	equ TempRect+8ZZEndofCursor	equ SaveRect+8Busy_M	equ $8000Shielded_M	equ $4000ForceU_M	equ $2000;;; Removed 5-Aug-91 DAL -- not compatible with the flickerless cursor stuff;	title 'UndrawCursor';****************************************************************;*;* iUndrawCursor;*;*;* 4/10/90	Mensch;*;* Added patch to allow for cursor handle being unlocked......;*;*;ROMUnDrawCursor	equ $FE41D2;	entry ReCalcCursorPtrs;****************************************************************;iUndrawCursor	PROC EXPORT;	jsr ReCalcCursorPtrs;	jml ROMUnDrawCursor	; and recall the ROM undraw routine;	EndP;	;	title 'drawCursor';****************************************************************;*;* idrawCursor;*;*;* 4/10/90	Mensch;*;* Added patch to allow for cursor handle being unlocked......;*;*;ROMDrawCursor	equ $FE40BD;****************************************************************;idrawCursor	PROC EXPORT;	jsr ReCalcCursorPtrs;	jml ROMDrawCursor	; and recall the ROM undraw routine;	EndP;;ReCalcCursorPtrs	proc Export;;;; This routine can be called by the draw or erase routines to determine if the;; cursor ptrs are correctly set up, this will allow us to leave the cursor image;; unlocked once its created so that it can move whenever needed;; NOTE: This relies on savesize being set properly...;;;; First determine if the handle has moved since the last time...;	lda SavePtr;	cmp [SaveHandle];	bne @DoRecalc;	ldy #2;	lda SavePtr+2	;24-Sep-90 DAL (This line was below instead);	cmp [SaveHandle],y;****	lda SavePtr+2;	bne @DoRecalc;	rts	; else, the pointers are set up just fine;@DoReca